// Enhanced Format Quick Response with role-based filtering and comprehensive formatting
// Based on your existing sophisticated roster formatting logic

// Get the quick response metadata from Has Quick Match node
const quickResponseData = $('Has Quick Match?').first().json;
const responseTemplate = quickResponseData.response_template;

// Get all SQL results from Execute Quick SQL node
const rosterData = $input.all();

// Check if we have enhanced roster data (with employee_role)
const hasEnhancedData = rosterData.length > 0 && rosterData[0].json && rosterData[0].json.employee_role;

let formattedResults = '';

if (!rosterData || rosterData.length === 0) {
  formattedResults = 'No results found.';
} else if (hasEnhancedData) {
  // Use enhanced formatting with role-based filtering

  // Shift mapping: A -> MORNING, B -> EVENING
  const shiftMapping = {
    'A': 'MORNING',
    'B': 'EVENING'
  };

  // Unavailable shift types mapping
  const unavailableMapping = {
    'L': 'On Leave',
    'WO': 'Weekly Off',
    'CO': 'Comp Off',
    'WH': 'WFH',
    'PH': 'Public Holiday'
  };

  // Group engineers by shift type
  const shiftGroups = {};
  const unavailableGroups = {};

  // Get the actual date from the roster data (for today/tomorrow queries)
  const rosterDate = rosterData[0].json.date; // e.g., "2025-11-28"
  const dateObj = new Date(rosterDate + 'T00:00:00'); // Parse as local date

  // Check if roster date is weekend or public holiday
  const dayOfWeek = dateObj.getDay(); // 0 = Sunday, 6 = Saturday
  const isWeekend = dayOfWeek === 0 || dayOfWeek === 6; // Sunday or Saturday

  // Check if it's a public holiday (count PH shifts)
  const phCount = rosterData.filter(item => item.json.shift === 'PH').length;
  const totalCount = rosterData.length;
  const isPublicHoliday = phCount > (totalCount * 0.5); // If more than 50% have PH shift

  // Process each roster entry with role-based filtering
  for (const item of rosterData) {
    const roster = item.json; // Access the actual data from n8n's structure
    const employeeName = roster.employee_name;
    const employeeRole = roster.employee_role;
    const shift = roster.shift;

    // MORNING SHIFT & EVENING SHIFT: Only show "Engineer" role
    if (shift === 'A' || shift === 'B' || shift === 'G') {
      if (employeeRole === 'Engineer') {
        // Map G shift to EVENING (same as B shift)
        const shiftType = shift === 'G' ? 'EVENING' : shiftMapping[shift];

        if (!shiftGroups[shiftType]) {
          shiftGroups[shiftType] = [];
        }
        shiftGroups[shiftType].push(employeeName);
      }
    }
    // AWH (Morning WFH): Only show "Engineer" role
    else if (shift === 'AWH') {
      if (employeeRole === 'Engineer') {
        const engineerName = employeeName + ' (WFH)';
        const shiftType = 'MORNING';

        if (!shiftGroups[shiftType]) {
          shiftGroups[shiftType] = [];
        }
        shiftGroups[shiftType].push(engineerName);
      }
    }
    // BWH (Evening WFH): Only show "Engineer" role
    else if (shift === 'BWH') {
      if (employeeRole === 'Engineer') {
        const engineerName = employeeName + ' (WFH)';
        const shiftType = 'EVENING';

        if (!shiftGroups[shiftType]) {
          shiftGroups[shiftType] = [];
        }
        shiftGroups[shiftType].push(engineerName);
      }
    }
    // WH (Work From Home - legacy): Only show "Engineer" role, defaults to EVENING
    else if (shift === 'WH') {
      if (employeeRole === 'Engineer') {
        const engineerName = employeeName + ' (WFH)';
        const shiftType = 'EVENING';

        if (!shiftGroups[shiftType]) {
          shiftGroups[shiftType] = [];
        }
        shiftGroups[shiftType].push(engineerName);
      }
    }
    // ENGINEERS NOT AVAILABLE: Show "Engineer" and "SME" roles only
    else if (unavailableMapping[shift] && !['WH', 'AWH', 'BWH'].includes(shift)) {
      if (employeeRole === 'Engineer' || employeeRole === 'SME') {
        const unavailableType = unavailableMapping[shift];

        if (!unavailableGroups[unavailableType]) {
          unavailableGroups[unavailableType] = [];
        }
        unavailableGroups[unavailableType].push(employeeName);
      }
    }
  }

  // Format the date from roster data (uses actual date from SQL query)
  const formattedDate = dateObj.toLocaleDateString('en-US', { 
    weekday: 'short', 
    month: 'short', 
    day: 'numeric',
    timeZone: 'Asia/Kolkata'
  });

  // Determine if we should hide unavailable section
  const hideUnavailableSection = isWeekend || isPublicHoliday;

  let message = `🗓️ **Daily Roster - ${formattedDate}**\n\n`;

  // Available Engineers Section
  if (Object.keys(shiftGroups).length === 0) {
    if (isWeekend || isPublicHoliday) {
      message += "🎉 **Weekend/Holiday** - No regular shifts scheduled\n\n";
    } else {
      message += "⚠️ No engineers scheduled for today (A/B shifts only).\n\n";
    }
  } else {
    message += "👨‍💼 **ENGINEERS ON DUTY**\n\n";

    // Show shifts in order: MORNING, EVENING
    const orderedShifts = ['MORNING', 'EVENING'];

    orderedShifts.forEach(shiftType => {
      if (shiftGroups[shiftType] && shiftGroups[shiftType].length > 0) {
        const engineers = shiftGroups[shiftType];
        const shiftCount = engineers.length;
        message += `🔧 **${shiftType} SHIFT (${shiftCount})**\n`;
        engineers.forEach(name => {
          message += `   • ${name}\n`;
        });
        message += "\n";
      }
    });
  }

  // Unavailable Engineers Section (only show on weekdays and non-public holidays)
  // Show only Engineers and SMEs who are not available
  if (!hideUnavailableSection && Object.keys(unavailableGroups).length > 0) {
    message += "🚫 **ENGINEERS NOT AVAILABLE**\n\n";

    // Show unavailable types in order
    const orderedUnavailable = ['On Leave', 'Weekly Off', 'Comp Off', 'WFH', 'Public Holiday'];

    orderedUnavailable.forEach(unavailableType => {
      if (unavailableGroups[unavailableType] && unavailableGroups[unavailableType].length > 0) {
        const engineers = unavailableGroups[unavailableType];
        let icon = '';
        switch(unavailableType) {
          case 'On Leave': icon = '🏖️'; break;
          case 'Weekly Off': icon = '🛌'; break;
          case 'Comp Off': icon = '💤'; break;
          case 'WFH': icon = '🏠'; break;
          case 'Public Holiday': icon = '🎉'; break;
        }

        message += `${icon} **${unavailableType.toUpperCase()}**\n`;
        engineers.forEach(name => {
          message += `   • ${name}\n`;
        });
        message += "\n";
      }
    });
  }

  // Calculate totals
  const totalOnDuty = Object.values(shiftGroups).reduce((sum, engineers) => sum + engineers.length, 0);
  const totalUnavailable = Object.values(unavailableGroups).reduce((sum, engineers) => sum + engineers.length, 0);

  formattedResults = message;

} else {
  // Fallback to simple formatting for backward compatibility
  // Check if results have name and shift_type (roster query)
  if (rosterData[0].json && rosterData[0].json.name && rosterData[0].json.shift_type) {
    // Group by shift_type
    const groupedByShift = {};
    rosterData.forEach(item => {
      const shift = item.json.shift_type;
      if (!groupedByShift[shift]) {
        groupedByShift[shift] = [];
      }
      groupedByShift[shift].push(item.json.name);
    });

    // Format grouped results
    const shiftNames = {
      'A': 'Morning (8AM-5PM)',
      'AWH': 'Morning WFH (8AM-5PM)',
      'B': 'Evening (11AM-8PM)',
      'BWH': 'Evening WFH (11AM-8PM)',
      'G': 'General (10AM-7PM)',
      'GWH': 'General WFH (10AM-7PM)',
      'WH': 'General (10AM-7PM)',
      'WFH': 'Work From Home',
      'WO': 'Weekly Off',
      'L': 'Leave',
      'PH': 'Public Holiday',
      'CO': 'Comp Off',
      'EWH': 'Evening WFH'
    };

    formattedResults = Object.keys(groupedByShift)
      .sort()
      .map(shift => {
        const shiftLabel = shiftNames[shift] || shift;
        const engineers = groupedByShift[shift].join(', ');
        return `${shiftLabel}: ${engineers}`;
      })
      .join('\n');
  } 
  // Check if results have only name (simple list query)
  else if (rosterData[0].json && rosterData[0].json.name) {
    const names = [];
    for (let i = 0; i < rosterData.length; i++) {
      if (rosterData[i].json && rosterData[i].json.name) {
        names.push(rosterData[i].json.name);
      }
    }
    formattedResults = names.join(', ');
  }
  // Generic fallback for any other structure
  else {
    formattedResults = rosterData.map(item => {
      if (item.json) {
        return Object.values(item.json).join(' | ');
      }
      return JSON.stringify(item);
    }).join('\n');
  }
}

// For enhanced formatting, ignore template and return formatted message directly
let finalResponse;
if (hasEnhancedData) {
  finalResponse = formattedResults; // Use the enhanced formatted message
} else {
  // Use template replacement for backward compatibility
  finalResponse = responseTemplate || 'Results: {{results}}';
  if (finalResponse && finalResponse.includes('{{results}}')) {
    finalResponse = finalResponse.replace('{{results}}', formattedResults);
  }
  if (finalResponse && finalResponse.includes('{{date}}')) {
    const currentDate = new Date().toLocaleDateString('en-GB');
    finalResponse = finalResponse.replace('{{date}}', currentDate);
  }
}

return {
  json: {
    formatted_response: finalResponse || formattedResults,
    query_pattern: quickResponseData.query_pattern || 'Unknown',
    result_count: rosterData.length,
    enhanced_formatting: hasEnhancedData,
    debug_data_sample: rosterData[0]?.json || 'No data'
  }
};

