// ── JWT Decode ─────────────────────────────────────────────────────────────
// Decodes the Bearer token passed in the POST body without a network call.
// Extracts: username, role, expiry.  The token signature was already validated
// by FastAPI at login time, so local decode is safe here.

const ROLE_LEVELS = {
  trainee: 1, engineer: 2, sme: 3, supervisor: 4,
  head: 5, admin: 6, superadmin: 7
};

const body  = $input.first().json.body || {};
const token = body.token || '';

const DENIED = (reason) => [{
  json: {
    authValid: false, reason,
    username: '', name: '', groups: [], highestRole: 'unknown',
    roleLevel: 0, canModifyOthers: false, body
  }
}];

if (!token) return DENIED('No token provided');

try {
  const parts = token.split('.');
  if (parts.length !== 3) return DENIED('Invalid JWT format');

  function b64urlDecode(str) {
    str = str.replace(/-/g, '+').replace(/_/g, '/');
    while (str.length % 4) str += '=';
    return Buffer.from(str, 'base64').toString('utf8');
  }

  const payload = JSON.parse(b64urlDecode(parts[1]));

  // Expiry check
  const nowSec = Math.floor(Date.now() / 1000);
  if (payload.exp && payload.exp < nowSec) return DENIED('Token expired');

  const username  = payload.preferred_username || payload.sub || '';
  const name      = payload.name || username;
  const groups    = (payload.groups || []).map(g => g.toLowerCase());
  const roleLevel = groups.length > 0
    ? Math.max(...groups.map(g => ROLE_LEVELS[g] || 0))
    : 0;
  const highestRole     = Object.entries(ROLE_LEVELS).find(([,v]) => v === roleLevel)?.[0] || 'unknown';
  const canModifyOthers = roleLevel >= 3; // sme and above

  return [{ json: { authValid: true, username, name, groups, roleLevel, highestRole, canModifyOthers, body } }];

} catch (e) {
  return DENIED(e.message);
}

// ── Permission Gate ─────────────────────────────────────────────────────────
// Enforces role-based access before any SQL is executed.
//
// Rules:
//   SELECT  → all roles allowed
//   UPDATE  → sme / supervisor / head / admin / superadmin: unrestricted
//   UPDATE  → engineer / trainee: only WHERE clause targets own username
//   other   → blocked (shouldn't reach here, but safeguard)

const sqlQuery        = ($json.output || '').trim();
const username        = ($('Set User Input').first().json.username || '').toLowerCase();
const roleLevel       = $('Decode JWT').first().json.roleLevel || 0;
const canModifyOthers = !!$('Set User Input').first().json.canModifyOthers;
const userRole        = $('Set User Input').first().json.userRole || 'unknown';

if (!sqlQuery) {
  return [{ json: { allowed: true, output: sqlQuery, permDenied: false } }];
}

const upperSQL = sqlQuery.toUpperCase().trim();

// SELECT — always allowed
if (upperSQL.startsWith('SELECT')) {
  return [{ json: { allowed: true, output: sqlQuery, permDenied: false } }];
}

// UPDATE — role check
if (upperSQL.startsWith('UPDATE')) {
  // sme+ can modify any record
  if (canModifyOthers) {
    return [{ json: { allowed: true, output: sqlQuery, permDenied: false } }];
  }
  // engineer/trainee — own record only
  if (roleLevel >= 1 && username && sqlQuery.toLowerCase().includes(username)) {
    return [{ json: { allowed: true, output: sqlQuery, permDenied: false } }];
  }
  // engineer/trainee trying to modify someone else
  return [{ json: {
    allowed: false, output: sqlQuery, permDenied: true,
    denyReason:
      `⛔ **Permission Denied**\n\nAs a **${userRole}**, you can only modify your own roster entries.\n` +
      `To update another team member's roster, please contact your supervisor.`
  }}];
}

// Anything else
return [{ json: {
  allowed: false, output: sqlQuery, permDenied: true,
  denyReason: '⛔ **Access Denied**\n\nThis operation is not permitted for your role.'
}}];
